fn frame(t: i32) {
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut hover: i32 = -1;
    if py >= 120 && py < 160 {
        if px >= 60 && px < 100 { hover = 0; }
        if px >= 140 && px < 180 { hover = 1; }
        if px >= 220 && px < 260 { hover = 2; }
    }
    let last: i32 = host::display::state_get(0) - 1;
    let mut frames: i32 = host::display::state_get(1);
    if hover == last { frames = frames + 1; } else { frames = 0; }
    host::display::state_set(0, hover + 1);
    host::display::state_set(1, frames);
    host::display::clear(0x101014);
    host::display::fill_rect(60, 120, 40, 40, 0x304060);
    host::display::fill_rect(140, 120, 40, 40, 0x304060);
    host::display::fill_rect(220, 120, 40, 40, 0x304060);
    host::display::draw_char(74, 132, 83, 0xffffff, 2);
    host::display::draw_char(154, 132, 76, 0xffffff, 2);
    host::display::draw_char(234, 132, 81, 0xffffff, 2);
    if hover >= 0 && frames > 30 {
        let tipx: i32 = 60 + hover * 80;
        host::display::fill_rect(tipx - 10, 82, 68, 26, 0x404040);
        host::display::fill_rect(tipx - 8, 84, 64, 22, 0x000000);
        if hover == 0 { host::display::draw_string(tipx, 92, "SAVE", 0xffff88, 1); }
        if hover == 1 { host::display::draw_string(tipx, 92, "LOAD", 0xffff88, 1); }
        if hover == 2 { host::display::draw_string(tipx, 92, "QUIT", 0xffff88, 1); }
    }
    host::display::draw_string(40, 40, "REST THE POINTER ON AN ICON", 0x808080, 1);
    host::display::present();
}
